<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class DormitoryManagementController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function floorStaff(Request $r){$this->manage($r);$rows=DB::table('dormitory_floor_staff as f')->join('dormitory_buildings as b','b.id','=','f.dormitory_building_id')->leftJoin('students as s','s.id','=','f.student_id')->leftJoin('users as u','u.id','=','f.user_id')->select('f.*','b.name building_name','s.last_name','s.first_name','u.name user_name')->orderBy('b.name')->orderBy('f.floor')->get();$buildings=DB::table('dormitory_buildings')->where('active',1)->get();$students=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('s.id','s.last_name','s.first_name')->orderBy('s.last_name')->get();return view('dormitory.floor-staff',compact('rows','buildings','students'));}
public function floorStaffStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_building_id'=>'required|exists:dormitory_buildings,id','floor'=>'required|integer|min:0|max:100','student_id'=>'required|exists:students,id','role'=>'required|in:floor_head,duty','from_on'=>'required|date','to_on'=>'nullable|date']);DB::table('dormitory_floor_staff')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function sanitation(Request $r){$this->manage($r);$rows=DB::table('dormitory_sanitary_checks as c')->join('dormitory_rooms as rm','rm.id','=','c.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('c.*','rm.number room_number','b.name building_name')->orderByDesc('c.checked_at')->limit(300)->get();$rooms=DB::table('dormitory_rooms as r')->join('dormitory_buildings as b','b.id','=','r.dormitory_building_id')->select('r.id','r.number','b.name building_name')->get();$rating=DB::table('dormitory_sanitary_checks as c')->join('dormitory_rooms as rm','rm.id','=','c.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('rm.id','rm.number','b.name',DB::raw('ROUND(AVG(c.total_score),1) avg_score'),DB::raw('COUNT(*) checks'))->groupBy('rm.id','rm.number','b.name')->orderByDesc('avg_score')->get();return view('dormitory.sanitation',compact('rows','rooms','rating'));}
public function sanitationStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_room_id'=>'required|exists:dormitory_rooms,id','checked_at'=>'required|date','cleanliness'=>'required|integer|min:1|max:5','order_score'=>'required|integer|min:1|max:5','safety'=>'required|integer|min:1|max:5','property_care'=>'required|integer|min:1|max:5','note'=>'nullable|string|max:3000']);$d['total_score']=$d['cleanliness']+$d['order_score']+$d['safety']+$d['property_care'];DB::table('dormitory_sanitary_checks')->insert($d+['checked_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function incidentFile(Request $r,$incident){$this->manage($r);abort_unless(DB::table('dormitory_incidents')->where('id',$incident)->exists(),404);$d=$r->validate(['file'=>'required|file|max:10240|mimes:jpg,jpeg,png,pdf,doc,docx']);$f=$r->file('file');$path=$f->store('dormitory/incidents/'.$incident,'local');DB::table('dormitory_incident_files')->insert(['dormitory_incident_id'=>$incident,'original_name'=>$f->getClientOriginalName(),'path'=>$path,'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'uploaded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function suggest(Request $r,$application){$this->manage($r);$a=DB::table('dormitory_applications')->find($application);abort_if(!$a,404);$s=DB::table('students')->find($a->student_id);$gender=$s->gender??null;$q=DB::table('dormitory_places as p')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where('p.status','available')->where('rm.status','available');if(in_array($gender,['male','female']))$q->whereIn('rm.gender',['any',$gender]);$place=$q->select('p.id','p.number place_number','rm.number room_number','rm.floor','b.name building_name')->orderByRaw("case when rm.gender='any' then 1 else 0 end")->orderBy('b.name')->orderBy('rm.floor')->first();abort_if(!$place,422,'Свободных подходящих мест нет');DB::table('dormitory_applications')->where('id',$application)->update(['suggested_place_id'=>$place->id,'updated_at'=>now()]);return back()->with('success','Предложено: '.$place->building_name.', комната '.$place->room_number.', место '.$place->place_number);}
}